/// What the host hands the codec as `obj` on decode: the destination, plus
/// the base pointer the spans are offsets into (ABI v1 section 7.4).
pub struct SinkUploadResultDataMessage<'a> {
    pub out: &'a mut UploadResultDataMessage,
    pub base: *const u8,
}

unsafe extern "C" fn apply_upload_result_data_message(
    ctx: *mut ak_dec_ctx,
    obj: *mut c_void,
    fx: *const ak_dfix_UploadResultDataMessage,
) {
    dguard(ctx, || {
        let s = &mut *(obj as *mut SinkUploadResultDataMessage);
        let f = &*fx;
        s.out.upload = if f.presence & AK_DFIX_UPLOADRESULTDATAMESSAGE_PRESENT_UPLOAD != 0 {
            Some(from_upload_result_data(&f.upload, s.base, ctx))
        } else {
            None
        };
        // Decision 11 (WP5 step 7): the root's own buffer, the host's now.
        s.out.unknown_fields = take_unk(&f.unknown);
    })
}

pub fn decode_with_upload_result_data_message(ctxs: DecCtxs, b: &[u8]) -> Result<UploadResultDataMessage, i32> {
    let ctx = ctxs.upload_result_data_message;
    let mut out = UploadResultDataMessage::default();
    let rc = unsafe {
        let mut sink = SinkUploadResultDataMessage { out: &mut out, base: b.as_ptr() };
        let vt = ak_dvt_UploadResultDataMessage {
            apply: Some(apply_upload_result_data_message),
        };
        ak_decode_UploadResultDataMessage(ctx, &mut sink as *mut _ as *mut c_void, b.as_ptr(), b.len(), &vt)
    };
    if rc < 0 { Err(rc) } else { Ok(out) }
}

/// Decision 11: every position of `UploadResultDataMessage` backed by `unk_grow` (no pre-allocated
/// buffer; a repeated position is an empty pool), except position `zero`, if
/// given, left all zero (discarded there).
pub fn unk_opts_upload_result_data_message(zero: Option<usize>) -> ak_dec_UploadResultDataMessage_opts {
    let e = ak_unk_opts { buf: ak_unk_buf { data: ::core::ptr::null_mut(), len: 0, cap: 0 }, grow: Some(unk_grow) };
    let z = ak_unk_opts { buf: ak_unk_buf { data: ::core::ptr::null_mut(), len: 0, cap: 0 }, grow: None };
    let pe = ak_unk_pool { bufs: ::core::ptr::null_mut(), n: 0, grow: Some(unk_grow) };
    let pz = ak_unk_pool { bufs: ::core::ptr::null_mut(), n: 0, grow: None };
    ak_dec_UploadResultDataMessage_opts {
        host: ::core::ptr::null_mut(),
        self_: if zero == Some(0) { z } else { e },
        upload: if zero == Some(1) { z } else { e },
    }
}
pub const UNK_POSITIONS_UPLOADRESULTDATAMESSAGE: usize = 2;

/// The same decode with the context armed with `opts` (read IN PLACE by the core
/// until the disarming reset), then disarmed; buffers the core placed but never
/// delivered (an inactive oneof member, a map entry, a failed decode) are reclaimed.
pub fn decode_with_upload_result_data_message_opts(ctxs: DecCtxs, b: &[u8], opts: &mut ak_dec_UploadResultDataMessage_opts) -> Result<UploadResultDataMessage, i32> {
    let rc = unsafe { ak_dec_reset_UploadResultDataMessage(ctxs.upload_result_data_message, opts) };
    if rc != AK_OK { return Err(rc); }
    let r = decode_with_upload_result_data_message(ctxs, b);
    unsafe { ak_dec_reset_UploadResultDataMessage(ctxs.upload_result_data_message, ::core::ptr::null_mut()); }
    unk_reclaim();
    r
}

/// Decision 11: retain everywhere.
pub fn decode_with_upload_result_data_message_unk(ctxs: DecCtxs, b: &[u8]) -> Result<UploadResultDataMessage, i32> {
    decode_with_upload_result_data_message_opts(ctxs, b, &mut unk_opts_upload_result_data_message(None))
}

/// Decision 11: the pull family (walk in place) with every position retained.
pub fn parse_walk_with_upload_result_data_message_unk(ctxs: DecCtxs, b: &[u8], toks: &mut Vec<i64>) -> Result<UploadResultDataMessage, i32> {
    let mut opts = unk_opts_upload_result_data_message(None);
    let rc = unsafe { ak_dec_reset_UploadResultDataMessage(ctxs.upload_result_data_message, &mut opts) };
    if rc != AK_OK { return Err(rc); }
    let r = parse_walk_with_upload_result_data_message(ctxs, b, toks);
    unsafe { ak_dec_reset_UploadResultDataMessage(ctxs.upload_result_data_message, ::core::ptr::null_mut()); }
    unk_reclaim();
    r
}

/// Decision 11 control: clear every bag at position `pos` (plan.unk_positions).
pub fn unk_clear_upload_result_data_message(o: &mut UploadResultDataMessage, pos: usize) {
    match pos {
        0 => { o.unknown_fields.clear(); }
        1 => { if let Some(x0) = o.upload.as_mut() { x0.unknown_fields.clear(); } }
        _ => {}
    }
}

pub fn unk_controls_upload_result_data_message(ctx: DecCtxs, b: &[u8], plant: bool) -> Result<UnkReport, i32> {
    const IS_ENTRY: [bool; 2] = [false, false];
    unk_entry_bytes();
    let all = decode_with_upload_result_data_message_unk(ctx, b)?;
    let eb_all = unk_entry_bytes();
    let mut toks = Vec::new();
    let pw = parse_walk_with_upload_result_data_message_unk(ctx, b, &mut toks)?;
    unk_entry_bytes();
    // Compared through Debug so a NaN equals itself (S-double-nan); bytes are the corpus's job.
    let dbg = |x: &UploadResultDataMessage| format!("{:?}", x);
    let mut rep = UnkReport { positions: 2, pull_equal: dbg(&pw) == dbg(&all), entry_bytes: eb_all, ..Default::default() };
    for i in 0..2 {
        let got = decode_with_upload_result_data_message_opts(ctx, b, &mut unk_opts_upload_result_data_message(Some(i)))?;
        let eb = unk_entry_bytes();
        let mut exp = all.clone();
        if !plant { unk_clear_upload_result_data_message(&mut exp, i); }
        if dbg(&exp) != dbg(&all) { rep.changed += 1; }
        if dbg(&got) != dbg(&exp) { rep.mismatched.push(i); }
        if eb != (if IS_ENTRY[i] { 0 } else { eb_all }) { rep.entry_mismatch.push(i); }
    }
    Ok(rep)
}

/// Replay one chunk of records (ABI v1 section 7.1: "walk heap arrays").
///
/// `toks` maps the token the CODEC minted, which is an index over the whole
/// parse, to the one `new_*` returned, which is an index into one host vector.
/// They coincide when a root has a single non-leaf slot and would not if it
/// had two, so the map is kept rather than the coincidence relied on.
///
/// **`OPAQUE` is R5's second half, for this family.** A replay is HOST code
/// calling host code, so rustc may inline `apply_*` and `add_*` into it and
/// specialise them; a push callback is reached through a vtable from across
/// the shared-library boundary and can never be. Subtracting the two families
/// without saying so would charge an optimiser difference to the interface.
/// With `OPAQUE`, every call goes through a `black_box`ed function pointer --
/// no inlining, no devirtualisation, no constant propagation -- which is the
/// same device the `core-native-opaque` arm already uses for the same reason.
/// A const generic, so the branch folds away in both instantiations.
unsafe fn replay_upload_result_data_message_g<const OPAQUE: bool>(
    ctx: *mut ak_dec_ctx,
    sink: *mut c_void,
    recs: &[u64],
    toks: &mut Vec<i64>,
) {
    macro_rules! c {
        ($f:expr) => {
            if OPAQUE { ::core::hint::black_box($f) } else { $f }
        };
    }
    for (h, body) in ak_rt::bdr::RecIter::new(recs) {
        match (h.op, h.slot) {
            (AK_BDR_APPLY, 0) => c!(apply_upload_result_data_message)(ctx, sink, body as *const ak_dfix_UploadResultDataMessage),
            // A record for a slot this host does not know is a generator
            // disagreement, not wire input, so it fails the operation rather
            // than being skipped the way an unknown TAG is.
            _ => ak_fail(ctx as *mut c_void, AK_ERR_ABI, ::core::ptr::null(), 0),
        }
    }
}

#[inline]
unsafe fn replay_upload_result_data_message(
    ctx: *mut ak_dec_ctx, sink: *mut c_void, recs: &[u64], toks: &mut Vec<i64>,
) {
    replay_upload_result_data_message_g::<false>(ctx, sink, recs, toks)
}

#[inline]
unsafe fn replay_upload_result_data_message_opaque(
    ctx: *mut ak_dec_ctx, sink: *mut c_void, recs: &[u64], toks: &mut Vec<i64>,
) {
    replay_upload_result_data_message_g::<true>(ctx, sink, recs, toks)
}

/// Pull, as a host that must COPY does it: parse, then drain in chunks into
/// the host's own memory and replay each chunk. This is the JVM shape --
/// `GetPrimitiveArrayCritical` over a `byte[]`, no upcall anywhere -- and the
/// copy is the part a native host does not need.
///
/// `scratch` is the host's chunk buffer, reused across calls so the arm
/// measures the family and not an allocator. `Vec<u64>`: a record payload is
/// an `ak_dfix_*` and has to be 8-aligned.
pub fn parse_drain_with_upload_result_data_message(
    ctxs: DecCtxs,
    b: &[u8],
    scratch: &mut Vec<u64>,
    toks: &mut Vec<i64>,
) -> Result<UploadResultDataMessage, i32> {
    let ctx = ctxs.upload_result_data_message;
    let mut out = UploadResultDataMessage::default();
    if scratch.len() * 8 < ak_rt::bdr::BDR_MIN_CHUNK {
        scratch.resize(ak_rt::bdr::BDR_MIN_CHUNK.div_ceil(8), 0);
    }
    toks.clear();
    let rc = unsafe {
        let rc = ak_parse_UploadResultDataMessage(ctx, b.as_ptr(), b.len());
        if rc < 0 {
            rc
        } else {
            let mut sink = SinkUploadResultDataMessage { out: &mut out, base: b.as_ptr() };
            let obj = &mut sink as *mut _ as *mut c_void;
            // Two forward calls the counting build cannot see from inside,
            // because `ak_bdr_footprint` takes a const context (R5).
            let total = ak_bdr_footprint(ctx);
            ak_bdr_count_forward(ctx, 1);
            let cap = scratch.len() * 8;
            let mut cursor = 0usize;
            let mut rc = AK_OK;
            while cursor < total {
                let n = ak_bdr_drain(ctx, scratch.as_mut_ptr() as *mut u8, cap, &mut cursor);
                if n < 0 { rc = n as i32; break; }
                if n == 0 { break; }
                replay_upload_result_data_message(ctx, obj, &scratch[..(n as usize) / 8], toks);
            }
            if rc == AK_OK { ak_dec_err(ctx) } else { rc }
        }
    };
    if rc < 0 { Err(rc) } else { Ok(out) }
}

